package org.zhixiaoce.aperture;
import android.view.*;import android.widget.*;import android.webkit.WebView;import org.json.*;
/** Read-only snapshot. Never reads input values, credentials, cookies, storage or arbitrary page scripts. */
final class LocalControlSemantics {
    static final String WEB_SCRIPT="(()=>Array.from(document.querySelectorAll('button,a,[role=button],[tabindex],h1,h2,time')).filter(e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>0&&r.height>0&&r.bottom>0&&r.top<innerHeight&&s.visibility!=='hidden'&&s.display!=='none'&&!e.closest('[hidden],[aria-hidden=true]')&&!['INPUT','TEXTAREA'].includes(e.tagName)}).slice(0,200).map((e,i)=>{const r=e.getBoundingClientRect();return {id:e.id||('web:'+i),role:e.getAttribute('role')||e.tagName.toLowerCase(),text:(e.getAttribute('aria-label')||e.innerText||'').slice(0,300),x:r.x,y:r.y,width:r.width,height:r.height,focused:document.activeElement===e,enabled:!e.disabled,viewportWidth:innerWidth}}))()";
    static WebView ownWeb(View view){if(view instanceof WebView){WebView web=(WebView)view;try{android.net.Uri uri=android.net.Uri.parse(web.getUrl());return LobbyAssets.HOST.equals(uri.getHost())&&LobbyAssets.DOCUMENT.equals(uri.getPath())?web:null;}catch(Exception absent){return null;}}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){WebView web=ownWeb(((ViewGroup)view).getChildAt(i));if(web!=null)return web;}return null;}
    static JSONArray nativeNodes(View root)throws Exception{JSONArray nodes=new JSONArray();tree(root,nodes,0);return nodes;}
    private static void tree(View v,JSONArray nodes,int depth)throws Exception{if(depth>20||nodes.length()>=300||v.getVisibility()!=View.VISIBLE)return;int[] xy=new int[2];v.getLocationOnScreen(xy);JSONObject n=new JSONObject().put("id",v.getId()).put("role",v.getClass().getSimpleName()).put("x",xy[0]).put("y",xy[1]).put("width",v.getWidth()).put("height",v.getHeight()).put("focused",v.isFocused()).put("enabled",v.isEnabled()).put("clickable",v.isClickable());if(!(v instanceof EditText)){if(v instanceof TextView)n.put("text",CinemaCatalog.field(((TextView)v).getText().toString(),300));if(v.getContentDescription()!=null)n.put("label",CinemaCatalog.field(v.getContentDescription().toString(),300));}nodes.put(n);if(v instanceof WebView)return;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)tree(((ViewGroup)v).getChildAt(i),nodes,depth+1);}
}
